// typebox's compile surface in miniature: a Validator whose Check is a
// negative type predicate over `unknown`, a generic Errors list, and a
// Compile overload pair so `ReturnType<typeof Compile>` narrows the
// generic arguments the way pi's real call site does.
class Validator {
  constructor(context, type) {
    this.hasCodec = false;
    this.buildResult = type;
  }
  Check(value) {
    return typeof value === "object" && value !== null && value.good === true;
  }
  Parse(value) {
    if (!this.Check(value)) throw new Error("parse failed");
    return value;
  }
  Errors(value) {
    if (this.Check(value)) return [];
    return [
      { keyword: "required", instancePath: "/path", message: "must be string", params: { requiredProperties: ["path"] } },
      { keyword: "type", instancePath: "/count", message: "must be number", params: {} },
    ];
  }
  Decode(value) {
    return this.Parse(value);
  }
}

function Compile(contextOrType, maybeType) {
  const type = maybeType === undefined ? contextOrType : maybeType;
  const context = maybeType === undefined ? {} : contextOrType;
  return new Validator(context, type);
}

const Type = {
  Object(properties) {
    return { "~kind": "Object", properties };
  },
  String() {
    return { "~kind": "String" };
  },
};

export { Compile, Type };
